                updateBreakdownUI(items, adapter, recyclerView, emptyStateLayout, emptyStateText, progressBar, "No unpaid transactions found")
            } catch (e: Exception) {
                Log.e("Supabase", "Error loading unpaid breakdown: ${e.message}", e)
